import React, { useEffect, useMemo } from 'react';
import { Link } from 'react-router-dom';
import Chart from 'react-apexcharts';
import { useSelector } from 'react-redux';

import StatusCard from '../components/status-card/StatusCard';
import Table from '../components/table/Table';
import Badge from '../components/badge/Badge';

import statusCardsData from '../assets/JsonData/status-card-data.json';


const chartData = {
    series: [{
        name: 'Hoạt động',
        data: [40, 70, 20, 90, 36, 80, 30, 91, 60, 50, 45, 75] 
    }, {
        name: 'Sản phẩm',
        data: [40, 30, 70, 80, 40, 16, 40, 20, 51, 10, 65, 35] 
    }],
    options: {
        color: ['#6ab04c', '#2980b9'],
        chart: {
            background: 'transparent',
        },
        dataLabels: {
            enabled: false
        },
        stroke: {
            curve: 'smooth'
        },
        xaxis: {
            categories: ['Tháng 1', 'Tháng 2', 'Tháng 3', 'Tháng 4', 'Tháng 5', 'Tháng 6', 'Tháng 7', 'Tháng 8', 'Tháng 9', 'Tháng 10', 'Tháng 11', 'Tháng 12'] // Đổi sang tên tháng cho trực quan
        },
        legend: {
            position: 'top'
        },
        grid: {
            show: false
        }
    }
};

const topCustomers = {
    head: [
        'Người dùng', 
        'Tổng đơn hàng', 
        'Tổng chi tiêu' 
    ],
    body: [
        { "username": "john doe", "order": "490", "price": "$15,870" },
        { "username": "frank iva", "order": "250", "price": "$12,251" },
        { "username": "anthony baker", "order": "120", "price": "$10,840" },
        { "username": "frank iva", "order": "110", "price": "$9,251" },
        { "username": "anthony baker", "order": "80", "price": "$8,840" }
    ]
};

const renderCustomerHead = (item, index) => (
    <th key={index}>{item}</th>
);

const renderCustomerBody = (item, index) => (
    <tr key={index}>
        <td>{item.username}</td>
        <td>{item.order}</td>
        <td>{item.price}</td>
    </tr>
);

const latestOrders = {
    header: [
        "Mã ĐH", 
        "Người dùng", 
        "Tổng tiền", 
        "Ngày", 
        "Trạng thái" 
    ],
    body: [
        { id: "#OD1711", user: "john doe", date: "17 Jun 2025", price: "$900", status: "shipping" },
        { id: "#OD1712", user: "frank iva", date: "1 Jun 2025", price: "$400", status: "paid" },
        { id: "#OD1713", user: "anthony baker", date: "27 Jun 2025", price: "$200", status: "pending" },
        { id: "#OD1712", user: "frank iva", date: "1 Jun 2025", price: "$400", status: "paid" },
        { id: "#OD1713", user: "anthony baker", date: "27 Jun 2025", price: "$200", status: "refund" }
    ]
};

const orderStatus = {
    "shipping": "primary", 
    "pending": "warning", 
    "paid": "success", 
    "refund": "danger" 
};

const renderOrderHead = (item, index) => (
    <th key={index}>{item}</th>
);

const renderOrderBody = (item, index) => (
    <tr key={index}>
        <td>{item.id}</td>
        <td>{item.user}</td>
        <td>{item.price}</td>
        <td>{item.date}</td>
        <td>
            <Badge type={orderStatus[item.status]} content={item.status}/>
        </td>
    </tr>
);


const Dashboard = () => {
    const themeReducer = useSelector(state => state.ThemeReducer.mode);

    const chartOptions = useMemo(() => ({
        ...chartData.options,
        theme: {
            mode: themeReducer === 'theme-mode-dark' ? 'dark' : 'light' 
        }
    }), [themeReducer]);


    return (
        <div>
            <h2 className="page-header">Dashboard </h2>
            <p style={{ marginBottom: "20px", fontWeight: "500", fontSize: "16px" }}>
                Chào mừng bạn đến với trang quản trị của shop!
            </p>
            
            <div className="row">
                <div className="col-12">
                    <div className="row">
                        <div className="col-6">
                            <div className="row">
                                {
                                    statusCardsData.map((item, index) => (
                                        <div className="col-6" key={index}>
                                            <StatusCard
                                                icon={item.icon}
                                                count={item.count}
                                                title={item.title}
                                            />
                                        </div>
                                    ))
                                }
                            </div>
                        </div>

                        <div className="col-6">
                            <div className="card full-height">
                                <Chart
                                    options={chartOptions}
                                    series={chartData.series}
                                    type='line'
                                    height='100%'
                                />
                            </div>
                        </div>
                    </div>
                </div>

                <div className="col-12">
                    <div className="row">
                        <div className="col-6">
                            <div className="card">
                                <div className="card__header">
                                    <h3>Khách hàng top</h3>
                                </div>
                                <div className="card__body">
                                    <Table
                                        headData={topCustomers.head}
                                        renderHead={(item, index) => renderCustomerHead(item, index)}
                                        bodyData={topCustomers.body}
                                        renderBody={(item, index) => renderCustomerBody(item, index)}
                                    />
                                </div>
                                <div className="card__footer">
                                    <Link to='/customers'>
                                        Xem tất cả
                                    </Link>
                                </div>
                            </div>
                        </div>

                        <div className="col-6">
                            <div className="card">
                                <div className="card__header">
                                    <h3>Đơn hàng mới nhất</h3>
                                </div>
                                <div className="card__body">
                                    <Table
                                        headData={latestOrders.header}
                                        renderHead={(item, index) => renderOrderHead(item, index)}
                                        bodyData={latestOrders.body}
                                        renderBody={(item, index) => renderOrderBody(item, index)}
                                    />
                                </div>
                                <div className="card__footer">
                                    <Link to='/orders'>
                                        Xem tất cả
                                    </Link>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    )
}

export default Dashboard;
